update public.learning_paths
set
  title = 'Acting I',
  goal = 'Acting I',
  summary = 'Acting I is a first-year studio course introducing the craft, discipline, vocabulary, and collaborative habits of actor training. Students learn to use body, voice, imagination, attention, and text analysis to create truthful, repeatable behavior under imaginary circumstances. The course balances Stanislavski-based action work, observation, improvisation, ensemble practice, beginner voice/body integration, ethical rehearsal norms, and introductory scene study. The course is designed as the gateway to Acting II, Voice and Movement, production practicum, script analysis, and later advanced performance work. It treats acting as both artistic exploration and professional practice: students take risks, but they do so inside clear structures of consent, preparation, feedback, and care.',
  data = $act1json${"slug": "acting-i", "title": "Acting I", "description": "Acting I is a first-year studio course introducing the craft, discipline, vocabulary, and collaborative habits of actor training. Students learn to use body, voice, imagination, attention, and text analysis to create truthful, repeatable behavior under imaginary circumstances. The course balances Stanislavski-based action work, observation, improvisation, ensemble practice, beginner voice/body integration, ethical rehearsal norms, and introductory scene study. The course is designed as the gateway to Acting II, Voice and Movement, production practicum, script analysis, and later advanced performance work. It treats acting as both artistic exploration and professional practice: students take risks, but they do so inside clear structures of consent, preparation, feedback, and care.", "topics": [{"id": "3956b03e-3527-432e-b1d5-ec6a180bd06e", "type": "topic", "title": "Relaxation and Concentration", "description": "This opening unit establishes the actor's capacity for focused, available, repeatable work. Students learn to release unhelpful tension, sustain attention under observation, and enter rehearsal with a calm, curious readiness.", "children": [{"id": "8e0641d0-3c0e-4c87-b4e9-9133f148f29b", "type": "subtopic", "title": "Productive Release", "children": [{"id": "457fb1ac-df4d-448e-866a-1f09271084c9", "type": "concept", "title": "Progressive relaxation and breath scanning"}, {"id": "0dba16be-2d1e-4464-9916-56ba7949177e", "type": "concept", "title": "Identifying habitual jaw, shoulder, chest, and hip tension"}, {"id": "55281195-173b-4733-974e-28b5eefe881c", "type": "concept", "title": "Reset rituals before rehearsal, audition, and performance"}], "description": "Actors distinguish release from collapse: the goal is alert freedom, not passivity."}, {"id": "7e32a2fb-4252-4bd2-8204-46b8696aab18", "type": "subtopic", "title": "Concentration Under Pressure", "children": [{"id": "928bb874-bbbb-408b-bca2-25c1f06d6374", "type": "concept", "title": "Public solitude and divided attention"}, {"id": "5888495b-82dc-44e4-967d-bc7941bcd461", "type": "concept", "title": "Focus anchors: breath, partner, environment, objective"}, {"id": "d9d15054-ffcd-47ac-a3b3-7f1bfa0ef1da", "type": "concept", "title": "Recovering after distraction without self-punishment"}], "description": "Students practice staying with an object, partner, task, or imagined circumstance while being watched."}, {"id": "45d16b44-a972-4679-9dae-69b9d6b16a78", "type": "subtopic", "title": "Studio Readiness", "children": [{"id": "ba4206af-5088-40ef-88eb-6ea16cef4dc2", "type": "concept", "title": "Warm-up sequence design"}, {"id": "6953119f-04e2-40e3-a5b5-4a7c56d9773c", "type": "concept", "title": "Journal check-ins and rehearsal intentions"}, {"id": "341d9e89-e755-42e3-8c0c-ed392bd3da85", "type": "concept", "title": "Respectful observation of peers as active learning"}], "description": "The unit turns preparation into a repeatable professional habit."}]}, {"id": "6f3e6859-500e-4403-a678-9d995964c662", "type": "topic", "title": "The Actor's Instrument", "description": "Actors work through body, voice, imagination, attention, and emotional availability. This section introduces the instrument as trainable and sustainable rather than mysterious talent.", "children": [{"id": "739352af-2c00-4fc4-80b2-beee226dfdcf", "type": "subtopic", "title": "Body, Voice, and Imagination", "children": [{"id": "62ebdaf8-288a-4209-84a1-835c03d14aa9", "type": "concept", "title": "Alignment, breath, resonance, articulation, gesture, and impulse"}, {"id": "32e4e6b1-7746-42eb-b3d8-f308075dda55", "type": "concept", "title": "Imagination as sensory, relational, and environmental specificity"}, {"id": "402e58fc-fe18-4e29-95a4-0284bc0b2efe", "type": "concept", "title": "The link between physical action and inner life"}], "description": "Students build a shared vocabulary for the physical, vocal, and imaginative dimensions of acting."}, {"id": "aaa7a2bb-447d-4652-af21-af6ff6c21001", "type": "subtopic", "title": "Presence and Availability", "children": [{"id": "99a84ff1-97a7-493c-864e-7c0202a040df", "type": "concept", "title": "Eye contact, listening, timing, stillness, and openness"}, {"id": "855978b9-3fab-42ba-9f48-0b557d0da47b", "type": "concept", "title": "Impulses versus habits"}, {"id": "ac2a1d3f-7ef1-4d5b-bd76-dfca261b507e", "type": "concept", "title": "Status, space, tempo, and energy as readable choices"}], "description": "The point is to become responsive to partners and circumstances in the present moment."}, {"id": "8e5b5217-d9f9-47ed-89b8-6458dc550f6b", "type": "subtopic", "title": "Sustainable Practice", "children": [{"id": "50ef0d1b-18a0-45ed-b505-e1f838f03208", "type": "concept", "title": "Vocal health and physical warm-downs"}, {"id": "5bdd357a-10c1-4d73-af67-0de24d2cd1d2", "type": "concept", "title": "Boundaries, consent, and intimacy-aware classroom practice"}, {"id": "76b6d8fe-ea86-4005-b528-59b621eac1d9", "type": "concept", "title": "Avoiding forced emotion and unsafe imitation"}], "description": "Students learn that acting craft includes care for the body, voice, and nervous system."}]}, {"id": "44abceef-68ae-4f19-9175-26cf69dd8a92", "type": "topic", "title": "Sense Memory and Observation", "description": "Observation trains actors to notice the world accurately, while sensory work deepens specificity. The unit uses memory carefully: as a route to detail and imagination, not as a demand for personal disclosure.", "children": [{"id": "e80a0a17-6516-4014-828d-600828fc85c7", "type": "subtopic", "title": "Sensory Specificity", "children": [{"id": "f410c218-9dfd-4310-8e97-6ba49a06ab27", "type": "concept", "title": "Temperature, texture, sound, smell, taste, weight, and distance"}, {"id": "45d04e7e-b6c0-44d6-8bc1-7517959aac1c", "type": "concept", "title": "Personalization without oversharing"}, {"id": "b63ad24e-8be7-4568-a82a-92b78139955f", "type": "concept", "title": "Object work and invisible environment exercises"}], "description": "Students learn to make imagined circumstances concrete enough to affect behavior."}, {"id": "e043f9ab-8583-4381-bc28-413c388c019a", "type": "subtopic", "title": "Observation of Human Behavior", "children": [{"id": "39488874-1b0e-4b32-90ab-09a5879546b7", "type": "concept", "title": "Gesture, rhythm, posture, speech patterns, and social masks"}, {"id": "753afbe9-5270-47e9-a173-4f5d755fc64b", "type": "concept", "title": "Observation journals and field notes"}, {"id": "7efeb848-51cf-46dd-84b4-cfc458700078", "type": "concept", "title": "Ethics of observing without caricature"}], "description": "Actors study behavior generously before turning it into character choices."}, {"id": "43591b4a-826d-49f0-b7c2-217c99b19ab1", "type": "subtopic", "title": "Memory, Imagination, and Safety", "children": [{"id": "1743759b-0efb-4857-ab24-eab9ce323004", "type": "concept", "title": "Consent-based boundaries around autobiographical material"}, {"id": "73e2412f-9dc3-4f58-9c9b-16eadcccd87a", "type": "concept", "title": "Substitution and imaginative equivalents"}, {"id": "3bfaf25c-5bbf-4f99-ae34-f77862ebe6e9", "type": "concept", "title": "Debriefing and returning to neutral"}], "description": "The class separates useful sensory recall from unsafe emotional mining."}]}, {"id": "b9ca3269-0a56-4dd3-b57c-60b1ea76f299", "type": "topic", "title": "Objectives and Playable Actions", "description": "This is the spine of practical acting technique. Students learn to convert analysis into active behavior: what the character wants, what they do to get it, and how tactics shift moment by moment.", "children": [{"id": "70566625-11f3-498c-85e6-59e4defb3507", "type": "subtopic", "title": "Objectives and Stakes", "children": [{"id": "33ae4a61-450c-4ab2-9117-93d53691c7cb", "type": "concept", "title": "Scene objective, moment-to-moment objective, and super-objective"}, {"id": "9c331400-ad32-4f3a-94fc-8c01a821ab53", "type": "concept", "title": "Stakes, need, obstacle, and consequence"}, {"id": "559cd19f-abfc-4608-9015-862b09fd8222", "type": "concept", "title": "Avoiding vague wants such as 'to be happy'"}], "description": "Students define playable wants that create urgency and relationship."}, {"id": "cd88f4e4-75bc-41ce-9cc6-1433ef2a73af", "type": "subtopic", "title": "Actions and Tactics", "children": [{"id": "65c17501-4b8d-499e-860c-8d937862b42c", "type": "concept", "title": "Playable transitive verbs: to persuade, protect, provoke, comfort"}, {"id": "95468e8d-9196-4aec-be56-6ffdc0765388", "type": "concept", "title": "Tactic shifts when obstacles appear"}, {"id": "65a09cf9-d115-492a-bc98-7aa05b11f874", "type": "concept", "title": "Action as behavior rather than mood"}], "description": "The unit trains verbs that can be acted with a partner."}, {"id": "19d4ed8d-214b-41bd-9323-bb60617a7219", "type": "subtopic", "title": "Conflict and Listening", "children": [{"id": "8a4dc41d-8ed7-4fd2-89b7-379428f7a34d", "type": "concept", "title": "Partner as source of evidence"}, {"id": "152d69e7-446f-4059-b0e8-9712a7f751e9", "type": "concept", "title": "Listening for change, not waiting to speak"}, {"id": "6d5abc23-9f6d-429b-b6d5-b6a12ff168b2", "type": "concept", "title": "Adjusting action based on response"}], "description": "Objectives become theatrical when they meet another person."}]}, {"id": "b508ee8d-249d-4f1e-bb6f-4eb75dffb123", "type": "topic", "title": "Given Circumstances, Beats, and Text Analysis", "description": "Students learn to read a script as an actor's score. The goal is not literary summary alone; it is to discover playable facts, relationships, events, and turning points.", "children": [{"id": "a3224e02-1962-4721-a540-7c6d7c10335c", "type": "subtopic", "title": "Given Circumstances", "children": [{"id": "5fb74f27-5496-44bd-812c-4991eacd28a7", "type": "concept", "title": "Who, where, when, what happened before, and what is at risk"}, {"id": "1710713a-f05d-4ac8-836f-a7dc2b99f543", "type": "concept", "title": "Social, historical, economic, and environmental circumstances"}, {"id": "15fc09cf-94a4-47a9-bcee-dc6ec2cf9f1b", "type": "concept", "title": "Research that changes behavior on stage"}], "description": "Actors ground choices in facts supplied by the script and production world."}, {"id": "a389ca52-0788-4bd6-afeb-f523a0b00ec3", "type": "subtopic", "title": "Beats and Events", "children": [{"id": "2b8f862b-6916-4c6f-95b6-82c79b65094d", "type": "concept", "title": "Beat shifts, events, reversals, discoveries, and entrances"}, {"id": "d88c9628-171f-490e-a9c8-fe18bf69a2c0", "type": "concept", "title": "Marking the script without overloading it"}, {"id": "b58b111f-22e9-497f-ba73-5463ea50294b", "type": "concept", "title": "Using beats to shape rehearsal runs"}], "description": "Students divide scenes according to changes in action, information, power, or tactic."}, {"id": "fd33f87c-3458-4c52-ad84-e50a825cc572", "type": "subtopic", "title": "Subtext and Speech Action", "children": [{"id": "1c045b4b-b782-432f-a123-21d654180bbf", "type": "concept", "title": "Subtext, silence, interruption, repetition, and avoidance"}, {"id": "36963e0f-cbf8-4741-ad78-074000283a36", "type": "concept", "title": "Operative words, punctuation, rhythm, and listening cues"}, {"id": "b103b3ed-67e6-4434-8956-fc28d28374d9", "type": "concept", "title": "Evidence-based choices rather than generalized feelings"}], "description": "Text work connects what is said to what is done."}]}, {"id": "d0c0afad-9d3e-44fa-990c-62e28f63db72", "type": "topic", "title": "Improvisation and Listening", "description": "Improvisation develops courage, responsiveness, ensemble trust, and moment-to-moment truth. It also helps students stop planning outcomes and start behaving under real conditions.", "children": [{"id": "b0b1d7df-f9a4-4055-ac27-3cdd08c6b7f8", "type": "subtopic", "title": "Yes-And and Offer Recognition", "children": [{"id": "d0987df0-f875-4853-b690-1702f79cac2a", "type": "concept", "title": "Offers, blocking, reincorporation, and shared focus"}, {"id": "955dd1fa-1da0-4381-af0a-663eb360f74c", "type": "concept", "title": "Specificity over cleverness"}, {"id": "69ea676d-08b9-4223-8844-c7959a1c4e45", "type": "concept", "title": "Supporting the scene partner's reality"}], "description": "Students practice accepting, building, and clarifying offers without grabbing control."}, {"id": "82321e2e-ed7f-4a20-9547-b2e48f72a848", "type": "subtopic", "title": "Impulse and Structure", "children": [{"id": "0c63cd88-b2d1-4d5b-901f-9cfe83c87426", "type": "concept", "title": "Rules of the game, objective, environment, and relationship"}, {"id": "e6589cd0-ca23-4985-8bf6-cb1f51034b62", "type": "concept", "title": "Improvising from circumstances rather than random invention"}, {"id": "07ad7100-ff91-44c5-836d-017a6de0a4b8", "type": "concept", "title": "Beginning, development, turn, and ending"}], "description": "Improvisation is freer when students understand the container."}, {"id": "989f48f8-747c-4364-a476-7dcaadcd7b87", "type": "subtopic", "title": "Risk, Failure, and Recovery", "children": [{"id": "4dfa9198-a705-4eda-a502-5e6b5d0400cc", "type": "concept", "title": "Trying boldly without self-editing"}, {"id": "965933bc-96b0-4f50-8a72-e157c6f1c889", "type": "concept", "title": "Recovering from dropped lines or broken focus"}, {"id": "3addc54b-2de3-4a84-9137-8657bbb7e14d", "type": "concept", "title": "Reflection after improvisation: what changed and why"}], "description": "The unit normalizes failed attempts as studio data."}]}, {"id": "0f762aab-dd1b-4af7-9fe3-4d98159eef04", "type": "topic", "title": "Voice, Speech, and Physical Readiness", "description": "Although a separate Voice and Movement course may follow, Acting I needs a working foundation in breath, speech, and physical expression so scene work can be heard, seen, and sustained.", "children": [{"id": "a6168ee0-7a90-4f29-b30f-c4e4c1d4e116", "type": "subtopic", "title": "Breath and Vocal Support", "children": [{"id": "2481e533-27dc-4a2b-a33f-46a554f545e9", "type": "concept", "title": "Low, released breath and supported phrase work"}, {"id": "553d3df5-a7e2-4b5c-91f3-c3caf5023cba", "type": "concept", "title": "Volume without strain"}, {"id": "ebf465c2-94eb-451d-a1db-7a8b514d08fa", "type": "concept", "title": "Breath as preparation for action"}], "description": "Students begin connecting breath to thought, intention, and sound."}, {"id": "69960b65-e56b-4767-ae0d-1e935193e247", "type": "subtopic", "title": "Articulation and Text Clarity", "children": [{"id": "9a639387-8531-446f-a569-5ac78b6a2e54", "type": "concept", "title": "Consonant precision, vowel energy, pace, and emphasis"}, {"id": "4f1ebc0d-00c6-4505-b0db-4512e940757f", "type": "concept", "title": "Handling contemporary, heightened, or unfamiliar language"}, {"id": "9a3b5500-9921-440e-832e-29fa77add2d2", "type": "concept", "title": "Clarity under movement and emotional stakes"}], "description": "Speech work makes choices intelligible without flattening character."}, {"id": "b17def70-52ac-4b2e-8a45-b0e25923f6eb", "type": "subtopic", "title": "Movement and Spatial Awareness", "children": [{"id": "40a2d92d-5221-434d-84ed-aa2c3cc05a1f", "type": "concept", "title": "Alignment, gesture, stillness, rhythm, and level"}, {"id": "4692b080-634d-4e08-bc7a-a9b43841bce1", "type": "concept", "title": "Blocking vocabulary and sightline awareness"}, {"id": "f11bd5c6-3fb4-44e0-abe5-65734ace6b85", "type": "concept", "title": "Physical choices that reveal relationship and status"}], "description": "The actor learns to use the stage as a partner."}]}, {"id": "a5534290-763e-4993-86db-27dee47a0369", "type": "topic", "title": "Scene Study Basics", "description": "Scene study brings the course tools together in partnered rehearsal. Students learn how to prepare, rehearse, revise, and perform a short scene with evidence-based choices.", "children": [{"id": "c902dd34-73f2-496c-a53b-b6d9efe769ce", "type": "subtopic", "title": "Scene Selection and Table Work", "children": [{"id": "b6628c64-4857-4ffc-a34d-54c49b9040d0", "type": "concept", "title": "Two-person contemporary scenes and short classical excerpts"}, {"id": "15961078-2453-4ca1-bdb1-0d5d83bd189b", "type": "concept", "title": "Initial reading for facts, events, relationship, and obstacles"}, {"id": "7090dcb1-0b3a-4706-ac3f-eec459b0e6c4", "type": "concept", "title": "Research packets and pronunciation questions"}], "description": "Students choose material that matches the course level and gives both partners active work."}, {"id": "9a40754e-faf1-4dc9-9337-f19d7cfbcce8", "type": "subtopic", "title": "Rehearsal Process", "children": [{"id": "c8ad8b27-d12a-4f28-8ad9-b46dd541fa4e", "type": "concept", "title": "Scheduling, memorization deadlines, run notes, and partner accountability"}, {"id": "2942ffa7-51d2-4a7c-b5f3-cf15cf40abb2", "type": "concept", "title": "Trying alternative actions and blocking options"}, {"id": "3576d1af-a611-4931-aabe-cfb8056dd2cc", "type": "concept", "title": "Recording discoveries in an actor's notebook"}], "description": "The unit teaches practical rehearsal habits instead of last-minute performance assembly."}, {"id": "aa7f34da-e1cb-44ad-83ef-73b5540a697a", "type": "subtopic", "title": "Coaching and Revision", "children": [{"id": "e99b578a-ab59-47b9-84ae-e7910b8a247e", "type": "concept", "title": "Receiving instructor and peer feedback"}, {"id": "9970bd9c-1053-441b-a094-a68643d4b8a5", "type": "concept", "title": "Translating notes into playable adjustments"}, {"id": "a325003b-deb4-445f-8a37-83120ce50f73", "type": "concept", "title": "Avoiding fixed line readings and premature polish"}], "description": "Students learn to use notes without losing ownership of choices."}]}, {"id": "3cb5968a-fb14-40d2-8f1b-0e6c5d439d90", "type": "topic", "title": "Character Work and Transformation", "description": "Character work asks students to build truthful behavior from circumstances, body, voice, imagination, and relationship. The emphasis is transformation with respect, not stereotype.", "children": [{"id": "85c5acf0-4d85-43db-9007-db557dd6b504", "type": "subtopic", "title": "Character Given Circumstances", "children": [{"id": "fc3e653f-ae65-4a48-bb0c-ce4c314f225f", "type": "concept", "title": "History, need, relationships, social world, and secrets"}, {"id": "e12bdfd0-2103-4c65-b55e-916012ce7672", "type": "concept", "title": "What the character knows versus what the actor knows"}, {"id": "81ecf116-f162-4870-9567-b9e9dc9dec40", "type": "concept", "title": "Character research connected to playable action"}], "description": "Students synthesize background facts into behavior rather than biography for its own sake."}, {"id": "16e65b5c-387c-4180-b34f-2adec7064bda", "type": "subtopic", "title": "Physical and Vocal Choices", "children": [{"id": "9c60074a-7edf-4b8a-bee5-b99fcd3e22a8", "type": "concept", "title": "Center, tempo, weight, gesture, and habitual action"}, {"id": "88be37c3-b6ad-418c-9a5c-069a37d48dd9", "type": "concept", "title": "Voice placement, pace, diction, and energy"}, {"id": "9131689f-0bee-4ee2-8565-6a5e400e6bbc", "type": "concept", "title": "Consistency without mechanical repetition"}], "description": "Actors explore how character lives in rhythm, posture, speech, and movement."}, {"id": "7084326d-f16e-4afc-be51-7fefcd22ffdc", "type": "subtopic", "title": "Ethics of Representation", "children": [{"id": "fc2c723b-7a2b-4de4-b979-8856ebab88e9", "type": "concept", "title": "Research beyond stereotype"}, {"id": "3c44f798-a7b8-4a0f-af10-e765a597adb7", "type": "concept", "title": "Consent and care when working with vulnerable material"}, {"id": "44c5f167-78ac-4b13-ba1d-ec12a272aa81", "type": "concept", "title": "Respectful boundaries around accent, body, and lived experience"}], "description": "The unit builds responsibility around identity, culture, trauma, disability, class, and accent."}]}, {"id": "9cab4b79-5771-41e7-9975-6ef39a01e7ed", "type": "topic", "title": "Ensemble Practice and Collaboration", "description": "Acting is never purely solo. Students learn ensemble awareness, shared rhythm, trust, and accountability as artistic skills that shape both process and performance.", "children": [{"id": "190543c6-95ec-43de-af3d-6d450e519a06", "type": "subtopic", "title": "Group Awareness", "children": [{"id": "651db367-06e7-41ce-b0f8-ab5c6758b4c8", "type": "concept", "title": "Peripheral awareness, shared tempo, group focus, and cueing"}, {"id": "b78fffb9-9037-4f55-87ac-51f70397cb4b", "type": "concept", "title": "Viewpoints-style time and space vocabulary"}, {"id": "cba474ec-c70f-47bd-ba71-5d7e566fc0c9", "type": "concept", "title": "Responding to the ensemble without overperforming"}], "description": "Students train attention across the whole room, not only their own part."}, {"id": "294f4df3-0f5d-485a-aecb-f6b5d71aedc3", "type": "subtopic", "title": "Trust and Consent", "children": [{"id": "85b12807-d0b5-459f-9ecb-3248ffc1e909", "type": "concept", "title": "Community agreements and check-ins"}, {"id": "584f11e5-cdde-4baa-9e4a-f6ef0762477a", "type": "concept", "title": "Touch, proximity, intimacy, and opt-out language"}, {"id": "8d7cfd18-ef36-4cb0-81fd-a86f2ca54b42", "type": "concept", "title": "Repair after miscommunication"}], "description": "Collaboration depends on boundaries that make risk possible."}, {"id": "7fba1909-5582-4ca0-98ef-afd90f2c8c53", "type": "subtopic", "title": "Peer Feedback", "children": [{"id": "e8817a9d-f11a-4ba6-9d8a-320a7962ec4e", "type": "concept", "title": "Observation before evaluation"}, {"id": "832932e3-6078-41a9-a74f-2016bbc7c8ba", "type": "concept", "title": "Feedback on actions, clarity, stakes, and listening"}, {"id": "95b8363d-4ac5-47de-8a31-d421a5539e43", "type": "concept", "title": "Separating taste from evidence"}], "description": "Students practice critique that is specific, kind, useful, and craft-based."}]}, {"id": "40ca209f-e520-4010-9c1b-a375f62b26b5", "type": "topic", "title": "Rehearsal Process and Professional Practice", "description": "A strong Acting I course should teach craft and conduct together. Students build habits that prepare them for productions, auditions, crews, and future studio sequences.", "children": [{"id": "ba7e46b1-56a1-447a-a915-fe3d7a991188", "type": "subtopic", "title": "Rehearsal Discipline", "children": [{"id": "a947505f-7467-4362-bd59-cc067f2e17ca", "type": "concept", "title": "Punctuality, memorization, script care, and rehearsal clothes"}, {"id": "d8175d54-c3b4-4bc0-b7e9-4cec1a810db0", "type": "concept", "title": "Notes etiquette and communication norms"}, {"id": "dab6bf92-f353-4c79-8a5e-522859c93213", "type": "concept", "title": "Tracking blocking, props, cuts, and changes"}], "description": "Students learn that preparation is an ethical obligation to collaborators."}, {"id": "462f23b4-39ac-4782-a664-ac58edd25d9f", "type": "subtopic", "title": "Audition and Monologue Foundations", "children": [{"id": "d9e8bb5b-4a8a-4000-b088-b08e9cc12a09", "type": "concept", "title": "Choosing age-appropriate material"}, {"id": "eadb8cf7-cbbf-4c19-885d-4b0c787b127c", "type": "concept", "title": "Slate, entrance, focus, and reset"}, {"id": "8c970d4c-02ac-4610-a81c-6fd567b62c56", "type": "concept", "title": "Objective, transition, and final beat in short monologues"}], "description": "The course introduces audition readiness without turning Acting I into an audition class."}, {"id": "b8e389ce-ade1-4961-a3b7-c7aa027d01b7", "type": "subtopic", "title": "Production Literacy", "children": [{"id": "79fe3ebd-20ff-47c7-8e29-ebfbe0d78a2a", "type": "concept", "title": "Director, stage manager, designer, dramaturg, and crew roles"}, {"id": "42ec0478-7e9b-4412-8779-9bbd9d8c560b", "type": "concept", "title": "Rehearsal room, tech, dress rehearsal, and performance etiquette"}, {"id": "643aa7e0-82a0-46aa-bb10-dbb769c69f7b", "type": "concept", "title": "Safety, access, and workplace expectations"}], "description": "Actors understand how their choices interact with the larger production system."}]}, {"id": "de32f029-737a-4ea2-8698-cb6bc530fdb5", "type": "topic", "title": "Performing a Scene and Reflective Growth", "description": "The final unit asks students to share prepared work, assess process honestly, and identify next steps. Performance is treated as a learning event, not only a graded product.", "children": [{"id": "b3e8eb86-178c-444d-b0e1-ccb5929a3570", "type": "subtopic", "title": "Final Scene Performance", "children": [{"id": "a7fddd47-eca1-4dbe-8cc6-5d91f6dd6091", "type": "concept", "title": "Memorized scene with rehearsed blocking"}, {"id": "eb034376-c6d8-4ef8-87a4-52d2ccbf53f4", "type": "concept", "title": "Specific given circumstances and playable actions"}, {"id": "b38d457b-3010-4418-a45f-528b6ec66aeb", "type": "concept", "title": "Recovery, presence, and responsiveness under audience attention"}], "description": "Students perform with clear objectives, active listening, vocal and physical clarity, and ensemble responsibility."}, {"id": "9f403817-6678-4e68-9295-3fcbe6780a20", "type": "subtopic", "title": "Performance Response", "children": [{"id": "e39df48b-bf0f-4ba4-92e6-17f7c62b8e18", "type": "concept", "title": "What changed in performance"}, {"id": "955fc8f2-c41b-4722-88a0-f9ef8a40b026", "type": "concept", "title": "Audience relationship and energy"}, {"id": "de4e0332-140d-4c0b-a4c4-2570be1b83a1", "type": "concept", "title": "Craft-based self-assessment and peer response"}], "description": "Students learn to discuss acting choices using evidence rather than vague praise or preference."}, {"id": "2208cb48-6a96-441e-87d9-68dbb03f697e", "type": "subtopic", "title": "Actor's Development Plan", "children": [{"id": "771c37f7-3f87-4916-866d-81c62be3091e", "type": "concept", "title": "Strengths, growth edges, and next studio goals"}, {"id": "7fdc3c39-b7cf-4dea-a83d-26c86e0791fa", "type": "concept", "title": "Warm-up and rehearsal habits to continue"}, {"id": "188a4386-5c57-40a5-ac98-4a3d8559fa65", "type": "concept", "title": "Preparation for Acting II, Voice and Movement, and production practicum"}], "description": "The course ends by turning feedback into a practical training plan."}]}], "dbBacked": true}$act1json$::jsonb,
