insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3956b03e-3527-432e-b1d5-ec6a180bd06e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Relaxation and Concentration', 'This opening unit establishes the actor''s capacity for focused, available, repeatable work. Students learn to release unhelpful tension, sustain attention under observation, and enter rehearsal with a calm, curious readiness.', 0),
  ('8e0641d0-3c0e-4c87-b4e9-9133f148f29b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '3956b03e-3527-432e-b1d5-ec6a180bd06e', 'subtopic'::public.curated_course_node_type, 'Productive Release', 'Actors distinguish release from collapse: the goal is alert freedom, not passivity.', 0),
  ('457fb1ac-df4d-448e-866a-1f09271084c9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '8e0641d0-3c0e-4c87-b4e9-9133f148f29b', 'concept'::public.curated_course_node_type, 'Progressive relaxation and breath scanning', null, 0),
  ('0dba16be-2d1e-4464-9916-56ba7949177e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '8e0641d0-3c0e-4c87-b4e9-9133f148f29b', 'concept'::public.curated_course_node_type, 'Identifying habitual jaw, shoulder, chest, and hip tension', null, 1),
  ('55281195-173b-4733-974e-28b5eefe881c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '8e0641d0-3c0e-4c87-b4e9-9133f148f29b', 'concept'::public.curated_course_node_type, 'Reset rituals before rehearsal, audition, and performance', null, 2),
  ('7e32a2fb-4252-4bd2-8204-46b8696aab18', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '3956b03e-3527-432e-b1d5-ec6a180bd06e', 'subtopic'::public.curated_course_node_type, 'Concentration Under Pressure', 'Students practice staying with an object, partner, task, or imagined circumstance while being watched.', 1),
  ('928bb874-bbbb-408b-bca2-25c1f06d6374', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7e32a2fb-4252-4bd2-8204-46b8696aab18', 'concept'::public.curated_course_node_type, 'Public solitude and divided attention', null, 0),
  ('5888495b-82dc-44e4-967d-bc7941bcd461', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7e32a2fb-4252-4bd2-8204-46b8696aab18', 'concept'::public.curated_course_node_type, 'Focus anchors: breath, partner, environment, objective', null, 1),
  ('d9d15054-ffcd-47ac-a3b3-7f1bfa0ef1da', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7e32a2fb-4252-4bd2-8204-46b8696aab18', 'concept'::public.curated_course_node_type, 'Recovering after distraction without self-punishment', null, 2),
  ('45d16b44-a972-4679-9dae-69b9d6b16a78', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '3956b03e-3527-432e-b1d5-ec6a180bd06e', 'subtopic'::public.curated_course_node_type, 'Studio Readiness', 'The unit turns preparation into a repeatable professional habit.', 2),
  ('ba4206af-5088-40ef-88eb-6ea16cef4dc2', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '45d16b44-a972-4679-9dae-69b9d6b16a78', 'concept'::public.curated_course_node_type, 'Warm-up sequence design', null, 0),
  ('6953119f-04e2-40e3-a5b5-4a7c56d9773c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '45d16b44-a972-4679-9dae-69b9d6b16a78', 'concept'::public.curated_course_node_type, 'Journal check-ins and rehearsal intentions', null, 1),
  ('341d9e89-e755-42e3-8c0c-ed392bd3da85', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '45d16b44-a972-4679-9dae-69b9d6b16a78', 'concept'::public.curated_course_node_type, 'Respectful observation of peers as active learning', null, 2),
  ('6f3e6859-500e-4403-a678-9d995964c662', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'The Actor''s Instrument', 'Actors work through body, voice, imagination, attention, and emotional availability. This section introduces the instrument as trainable and sustainable rather than mysterious talent.', 1),
  ('739352af-2c00-4fc4-80b2-beee226dfdcf', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '6f3e6859-500e-4403-a678-9d995964c662', 'subtopic'::public.curated_course_node_type, 'Body, Voice, and Imagination', 'Students build a shared vocabulary for the physical, vocal, and imaginative dimensions of acting.', 0),
  ('62ebdaf8-288a-4209-84a1-835c03d14aa9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '739352af-2c00-4fc4-80b2-beee226dfdcf', 'concept'::public.curated_course_node_type, 'Alignment, breath, resonance, articulation, gesture, and impulse', null, 0),
  ('32e4e6b1-7746-42eb-b3d8-f308075dda55', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '739352af-2c00-4fc4-80b2-beee226dfdcf', 'concept'::public.curated_course_node_type, 'Imagination as sensory, relational, and environmental specificity', null, 1),
  ('402e58fc-fe18-4e29-95a4-0284bc0b2efe', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '739352af-2c00-4fc4-80b2-beee226dfdcf', 'concept'::public.curated_course_node_type, 'The link between physical action and inner life', null, 2),
  ('aaa7a2bb-447d-4652-af21-af6ff6c21001', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '6f3e6859-500e-4403-a678-9d995964c662', 'subtopic'::public.curated_course_node_type, 'Presence and Availability', 'The point is to become responsive to partners and circumstances in the present moment.', 1),
  ('99a84ff1-97a7-493c-864e-7c0202a040df', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'aaa7a2bb-447d-4652-af21-af6ff6c21001', 'concept'::public.curated_course_node_type, 'Eye contact, listening, timing, stillness, and openness', null, 0),
  ('855978b9-3fab-42ba-9f48-0b557d0da47b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'aaa7a2bb-447d-4652-af21-af6ff6c21001', 'concept'::public.curated_course_node_type, 'Impulses versus habits', null, 1),
  ('ac2a1d3f-7ef1-4d5b-bd76-dfca261b507e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'aaa7a2bb-447d-4652-af21-af6ff6c21001', 'concept'::public.curated_course_node_type, 'Status, space, tempo, and energy as readable choices', null, 2),
  ('8e5b5217-d9f9-47ed-89b8-6458dc550f6b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '6f3e6859-500e-4403-a678-9d995964c662', 'subtopic'::public.curated_course_node_type, 'Sustainable Practice', 'Students learn that acting craft includes care for the body, voice, and nervous system.', 2),
  ('50ef0d1b-18a0-45ed-b505-e1f838f03208', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '8e5b5217-d9f9-47ed-89b8-6458dc550f6b', 'concept'::public.curated_course_node_type, 'Vocal health and physical warm-downs', null, 0),
  ('5bdd357a-10c1-4d73-af67-0de24d2cd1d2', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '8e5b5217-d9f9-47ed-89b8-6458dc550f6b', 'concept'::public.curated_course_node_type, 'Boundaries, consent, and intimacy-aware classroom practice', null, 1),
  ('76b6d8fe-ea86-4005-b528-59b621eac1d9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '8e5b5217-d9f9-47ed-89b8-6458dc550f6b', 'concept'::public.curated_course_node_type, 'Avoiding forced emotion and unsafe imitation', null, 2),
  ('44abceef-68ae-4f19-9175-26cf69dd8a92', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Sense Memory and Observation', 'Observation trains actors to notice the world accurately, while sensory work deepens specificity. The unit uses memory carefully: as a route to detail and imagination, not as a demand for personal disclosure.', 2),
  ('e80a0a17-6516-4014-828d-600828fc85c7', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '44abceef-68ae-4f19-9175-26cf69dd8a92', 'subtopic'::public.curated_course_node_type, 'Sensory Specificity', 'Students learn to make imagined circumstances concrete enough to affect behavior.', 0),
  ('f410c218-9dfd-4310-8e97-6ba49a06ab27', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'e80a0a17-6516-4014-828d-600828fc85c7', 'concept'::public.curated_course_node_type, 'Temperature, texture, sound, smell, taste, weight, and distance', null, 0),
  ('45d04e7e-b6c0-44d6-8bc1-7517959aac1c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'e80a0a17-6516-4014-828d-600828fc85c7', 'concept'::public.curated_course_node_type, 'Personalization without oversharing', null, 1),
  ('b63ad24e-8be7-4568-a82a-92b78139955f', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'e80a0a17-6516-4014-828d-600828fc85c7', 'concept'::public.curated_course_node_type, 'Object work and invisible environment exercises', null, 2),
  ('e043f9ab-8583-4381-bc28-413c388c019a', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '44abceef-68ae-4f19-9175-26cf69dd8a92', 'subtopic'::public.curated_course_node_type, 'Observation of Human Behavior', 'Actors study behavior generously before turning it into character choices.', 1),
  ('39488874-1b0e-4b32-90ab-09a5879546b7', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'e043f9ab-8583-4381-bc28-413c388c019a', 'concept'::public.curated_course_node_type, 'Gesture, rhythm, posture, speech patterns, and social masks', null, 0),
  ('753afbe9-5270-47e9-a173-4f5d755fc64b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'e043f9ab-8583-4381-bc28-413c388c019a', 'concept'::public.curated_course_node_type, 'Observation journals and field notes', null, 1),
  ('7efeb848-51cf-46dd-84b4-cfc458700078', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'e043f9ab-8583-4381-bc28-413c388c019a', 'concept'::public.curated_course_node_type, 'Ethics of observing without caricature', null, 2),
  ('43591b4a-826d-49f0-b7c2-217c99b19ab1', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '44abceef-68ae-4f19-9175-26cf69dd8a92', 'subtopic'::public.curated_course_node_type, 'Memory, Imagination, and Safety', 'The class separates useful sensory recall from unsafe emotional mining.', 2),
  ('1743759b-0efb-4857-ab24-eab9ce323004', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '43591b4a-826d-49f0-b7c2-217c99b19ab1', 'concept'::public.curated_course_node_type, 'Consent-based boundaries around autobiographical material', null, 0),
  ('73e2412f-9dc3-4f58-9c9b-16eadcccd87a', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '43591b4a-826d-49f0-b7c2-217c99b19ab1', 'concept'::public.curated_course_node_type, 'Substitution and imaginative equivalents', null, 1),
  ('3bfaf25c-5bbf-4f99-ae34-f77862ebe6e9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '43591b4a-826d-49f0-b7c2-217c99b19ab1', 'concept'::public.curated_course_node_type, 'Debriefing and returning to neutral', null, 2),
  ('b9ca3269-0a56-4dd3-b57c-60b1ea76f299', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Objectives and Playable Actions', 'This is the spine of practical acting technique. Students learn to convert analysis into active behavior: what the character wants, what they do to get it, and how tactics shift moment by moment.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('70566625-11f3-498c-85e6-59e4defb3507', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b9ca3269-0a56-4dd3-b57c-60b1ea76f299', 'subtopic'::public.curated_course_node_type, 'Objectives and Stakes', 'Students define playable wants that create urgency and relationship.', 0),
  ('33ae4a61-450c-4ab2-9117-93d53691c7cb', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '70566625-11f3-498c-85e6-59e4defb3507', 'concept'::public.curated_course_node_type, 'Scene objective, moment-to-moment objective, and super-objective', null, 0),
