  ('559cd19f-abfc-4608-9015-862b09fd8222', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '70566625-11f3-498c-85e6-59e4defb3507', 'concept'::public.curated_course_node_type, 'Avoiding vague wants such as ''to be happy''', null, 2),
  ('cd88f4e4-75bc-41ce-9cc6-1433ef2a73af', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b9ca3269-0a56-4dd3-b57c-60b1ea76f299', 'subtopic'::public.curated_course_node_type, 'Actions and Tactics', 'The unit trains verbs that can be acted with a partner.', 1),
  ('65c17501-4b8d-499e-860c-8d937862b42c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'cd88f4e4-75bc-41ce-9cc6-1433ef2a73af', 'concept'::public.curated_course_node_type, 'Playable transitive verbs: to persuade, protect, provoke, comfort', null, 0),
  ('95468e8d-9196-4aec-be56-6ffdc0765388', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'cd88f4e4-75bc-41ce-9cc6-1433ef2a73af', 'concept'::public.curated_course_node_type, 'Tactic shifts when obstacles appear', null, 1),
  ('65a09cf9-d115-492a-bc98-7aa05b11f874', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'cd88f4e4-75bc-41ce-9cc6-1433ef2a73af', 'concept'::public.curated_course_node_type, 'Action as behavior rather than mood', null, 2),
  ('19d4ed8d-214b-41bd-9323-bb60617a7219', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b9ca3269-0a56-4dd3-b57c-60b1ea76f299', 'subtopic'::public.curated_course_node_type, 'Conflict and Listening', 'Objectives become theatrical when they meet another person.', 2),
  ('8a4dc41d-8ed7-4fd2-89b7-379428f7a34d', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '19d4ed8d-214b-41bd-9323-bb60617a7219', 'concept'::public.curated_course_node_type, 'Partner as source of evidence', null, 0),
  ('152d69e7-446f-4059-b0e8-9712a7f751e9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '19d4ed8d-214b-41bd-9323-bb60617a7219', 'concept'::public.curated_course_node_type, 'Listening for change, not waiting to speak', null, 1),
  ('6d5abc23-9f6d-429b-b6d5-b6a12ff168b2', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '19d4ed8d-214b-41bd-9323-bb60617a7219', 'concept'::public.curated_course_node_type, 'Adjusting action based on response', null, 2),
  ('b508ee8d-249d-4f1e-bb6f-4eb75dffb123', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Given Circumstances, Beats, and Text Analysis', 'Students learn to read a script as an actor''s score. The goal is not literary summary alone; it is to discover playable facts, relationships, events, and turning points.', 4),
  ('a3224e02-1962-4721-a540-7c6d7c10335c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b508ee8d-249d-4f1e-bb6f-4eb75dffb123', 'subtopic'::public.curated_course_node_type, 'Given Circumstances', 'Actors ground choices in facts supplied by the script and production world.', 0),
  ('5fb74f27-5496-44bd-812c-4991eacd28a7', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a3224e02-1962-4721-a540-7c6d7c10335c', 'concept'::public.curated_course_node_type, 'Who, where, when, what happened before, and what is at risk', null, 0),
  ('1710713a-f05d-4ac8-836f-a7dc2b99f543', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a3224e02-1962-4721-a540-7c6d7c10335c', 'concept'::public.curated_course_node_type, 'Social, historical, economic, and environmental circumstances', null, 1),
  ('15fc09cf-94a4-47a9-bcee-dc6ec2cf9f1b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a3224e02-1962-4721-a540-7c6d7c10335c', 'concept'::public.curated_course_node_type, 'Research that changes behavior on stage', null, 2),
  ('a389ca52-0788-4bd6-afeb-f523a0b00ec3', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b508ee8d-249d-4f1e-bb6f-4eb75dffb123', 'subtopic'::public.curated_course_node_type, 'Beats and Events', 'Students divide scenes according to changes in action, information, power, or tactic.', 1),
  ('2b8f862b-6916-4c6f-95b6-82c79b65094d', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a389ca52-0788-4bd6-afeb-f523a0b00ec3', 'concept'::public.curated_course_node_type, 'Beat shifts, events, reversals, discoveries, and entrances', null, 0),
  ('d88c9628-171f-490e-a9c8-fe18bf69a2c0', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a389ca52-0788-4bd6-afeb-f523a0b00ec3', 'concept'::public.curated_course_node_type, 'Marking the script without overloading it', null, 1),
  ('b58b111f-22e9-497f-ba73-5463ea50294b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a389ca52-0788-4bd6-afeb-f523a0b00ec3', 'concept'::public.curated_course_node_type, 'Using beats to shape rehearsal runs', null, 2),
  ('fd33f87c-3458-4c52-ad84-e50a825cc572', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b508ee8d-249d-4f1e-bb6f-4eb75dffb123', 'subtopic'::public.curated_course_node_type, 'Subtext and Speech Action', 'Text work connects what is said to what is done.', 2),
  ('1c045b4b-b782-432f-a123-21d654180bbf', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'fd33f87c-3458-4c52-ad84-e50a825cc572', 'concept'::public.curated_course_node_type, 'Subtext, silence, interruption, repetition, and avoidance', null, 0),
  ('36963e0f-cbf8-4741-ad78-074000283a36', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'fd33f87c-3458-4c52-ad84-e50a825cc572', 'concept'::public.curated_course_node_type, 'Operative words, punctuation, rhythm, and listening cues', null, 1),
  ('b103b3ed-67e6-4434-8956-fc28d28374d9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'fd33f87c-3458-4c52-ad84-e50a825cc572', 'concept'::public.curated_course_node_type, 'Evidence-based choices rather than generalized feelings', null, 2),
  ('d0c0afad-9d3e-44fa-990c-62e28f63db72', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Improvisation and Listening', 'Improvisation develops courage, responsiveness, ensemble trust, and moment-to-moment truth. It also helps students stop planning outcomes and start behaving under real conditions.', 5),
  ('b0b1d7df-f9a4-4055-ac27-3cdd08c6b7f8', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'd0c0afad-9d3e-44fa-990c-62e28f63db72', 'subtopic'::public.curated_course_node_type, 'Yes-And and Offer Recognition', 'Students practice accepting, building, and clarifying offers without grabbing control.', 0),
  ('d0987df0-f875-4853-b690-1702f79cac2a', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b0b1d7df-f9a4-4055-ac27-3cdd08c6b7f8', 'concept'::public.curated_course_node_type, 'Offers, blocking, reincorporation, and shared focus', null, 0),
  ('955dd1fa-1da0-4381-af0a-663eb360f74c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b0b1d7df-f9a4-4055-ac27-3cdd08c6b7f8', 'concept'::public.curated_course_node_type, 'Specificity over cleverness', null, 1),
  ('69ea676d-08b9-4223-8844-c7959a1c4e45', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b0b1d7df-f9a4-4055-ac27-3cdd08c6b7f8', 'concept'::public.curated_course_node_type, 'Supporting the scene partner''s reality', null, 2),
  ('82321e2e-ed7f-4a20-9547-b2e48f72a848', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'd0c0afad-9d3e-44fa-990c-62e28f63db72', 'subtopic'::public.curated_course_node_type, 'Impulse and Structure', 'Improvisation is freer when students understand the container.', 1),
  ('0c63cd88-b2d1-4d5b-901f-9cfe83c87426', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '82321e2e-ed7f-4a20-9547-b2e48f72a848', 'concept'::public.curated_course_node_type, 'Rules of the game, objective, environment, and relationship', null, 0),
  ('e6589cd0-ca23-4985-8bf6-cb1f51034b62', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '82321e2e-ed7f-4a20-9547-b2e48f72a848', 'concept'::public.curated_course_node_type, 'Improvising from circumstances rather than random invention', null, 1),
  ('07ad7100-ff91-44c5-836d-017a6de0a4b8', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '82321e2e-ed7f-4a20-9547-b2e48f72a848', 'concept'::public.curated_course_node_type, 'Beginning, development, turn, and ending', null, 2),
  ('989f48f8-747c-4364-a476-7dcaadcd7b87', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'd0c0afad-9d3e-44fa-990c-62e28f63db72', 'subtopic'::public.curated_course_node_type, 'Risk, Failure, and Recovery', 'The unit normalizes failed attempts as studio data.', 2),
  ('4dfa9198-a705-4eda-a502-5e6b5d0400cc', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '989f48f8-747c-4364-a476-7dcaadcd7b87', 'concept'::public.curated_course_node_type, 'Trying boldly without self-editing', null, 0),
  ('965933bc-96b0-4f50-8a72-e157c6f1c889', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '989f48f8-747c-4364-a476-7dcaadcd7b87', 'concept'::public.curated_course_node_type, 'Recovering from dropped lines or broken focus', null, 1),
  ('3addc54b-2de3-4a84-9137-8657bbb7e14d', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '989f48f8-747c-4364-a476-7dcaadcd7b87', 'concept'::public.curated_course_node_type, 'Reflection after improvisation: what changed and why', null, 2),
  ('0f762aab-dd1b-4af7-9fe3-4d98159eef04', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Voice, Speech, and Physical Readiness', 'Although a separate Voice and Movement course may follow, Acting I needs a working foundation in breath, speech, and physical expression so scene work can be heard, seen, and sustained.', 6),
  ('a6168ee0-7a90-4f29-b30f-c4e4c1d4e116', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '0f762aab-dd1b-4af7-9fe3-4d98159eef04', 'subtopic'::public.curated_course_node_type, 'Breath and Vocal Support', 'Students begin connecting breath to thought, intention, and sound.', 0);
