values
  ('2481e533-27dc-4a2b-a33f-46a554f545e9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a6168ee0-7a90-4f29-b30f-c4e4c1d4e116', 'concept'::public.curated_course_node_type, 'Low, released breath and supported phrase work', null, 0),
