  ('ebf465c2-94eb-451d-a1db-7a8b514d08fa', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a6168ee0-7a90-4f29-b30f-c4e4c1d4e116', 'concept'::public.curated_course_node_type, 'Breath as preparation for action', null, 2),
  ('69960b65-e56b-4767-ae0d-1e935193e247', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '0f762aab-dd1b-4af7-9fe3-4d98159eef04', 'subtopic'::public.curated_course_node_type, 'Articulation and Text Clarity', 'Speech work makes choices intelligible without flattening character.', 1),
  ('9a639387-8531-446f-a569-5ac78b6a2e54', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '69960b65-e56b-4767-ae0d-1e935193e247', 'concept'::public.curated_course_node_type, 'Consonant precision, vowel energy, pace, and emphasis', null, 0),
  ('4f1ebc0d-00c6-4505-b0db-4512e940757f', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '69960b65-e56b-4767-ae0d-1e935193e247', 'concept'::public.curated_course_node_type, 'Handling contemporary, heightened, or unfamiliar language', null, 1),
  ('9a3b5500-9921-440e-832e-29fa77add2d2', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '69960b65-e56b-4767-ae0d-1e935193e247', 'concept'::public.curated_course_node_type, 'Clarity under movement and emotional stakes', null, 2),
  ('b17def70-52ac-4b2e-8a45-b0e25923f6eb', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '0f762aab-dd1b-4af7-9fe3-4d98159eef04', 'subtopic'::public.curated_course_node_type, 'Movement and Spatial Awareness', 'The actor learns to use the stage as a partner.', 2),
  ('40a2d92d-5221-434d-84ed-aa2c3cc05a1f', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b17def70-52ac-4b2e-8a45-b0e25923f6eb', 'concept'::public.curated_course_node_type, 'Alignment, gesture, stillness, rhythm, and level', null, 0),
  ('4692b080-634d-4e08-bc7a-a9b43841bce1', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b17def70-52ac-4b2e-8a45-b0e25923f6eb', 'concept'::public.curated_course_node_type, 'Blocking vocabulary and sightline awareness', null, 1),
  ('f11bd5c6-3fb4-44e0-abe5-65734ace6b85', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b17def70-52ac-4b2e-8a45-b0e25923f6eb', 'concept'::public.curated_course_node_type, 'Physical choices that reveal relationship and status', null, 2),
  ('a5534290-763e-4993-86db-27dee47a0369', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Scene Study Basics', 'Scene study brings the course tools together in partnered rehearsal. Students learn how to prepare, rehearse, revise, and perform a short scene with evidence-based choices.', 7),
  ('c902dd34-73f2-496c-a53b-b6d9efe769ce', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a5534290-763e-4993-86db-27dee47a0369', 'subtopic'::public.curated_course_node_type, 'Scene Selection and Table Work', 'Students choose material that matches the course level and gives both partners active work.', 0),
  ('b6628c64-4857-4ffc-a34d-54c49b9040d0', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'c902dd34-73f2-496c-a53b-b6d9efe769ce', 'concept'::public.curated_course_node_type, 'Two-person contemporary scenes and short classical excerpts', null, 0),
  ('15961078-2453-4ca1-bdb1-0d5d83bd189b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'c902dd34-73f2-496c-a53b-b6d9efe769ce', 'concept'::public.curated_course_node_type, 'Initial reading for facts, events, relationship, and obstacles', null, 1),
  ('7090dcb1-0b3a-4706-ac3f-eec459b0e6c4', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'c902dd34-73f2-496c-a53b-b6d9efe769ce', 'concept'::public.curated_course_node_type, 'Research packets and pronunciation questions', null, 2),
  ('9a40754e-faf1-4dc9-9337-f19d7cfbcce8', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a5534290-763e-4993-86db-27dee47a0369', 'subtopic'::public.curated_course_node_type, 'Rehearsal Process', 'The unit teaches practical rehearsal habits instead of last-minute performance assembly.', 1),
  ('c8ad8b27-d12a-4f28-8ad9-b46dd541fa4e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9a40754e-faf1-4dc9-9337-f19d7cfbcce8', 'concept'::public.curated_course_node_type, 'Scheduling, memorization deadlines, run notes, and partner accountability', null, 0),
  ('2942ffa7-51d2-4a7c-b5f3-cf15cf40abb2', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9a40754e-faf1-4dc9-9337-f19d7cfbcce8', 'concept'::public.curated_course_node_type, 'Trying alternative actions and blocking options', null, 1),
  ('3576d1af-a611-4931-aabe-cfb8056dd2cc', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9a40754e-faf1-4dc9-9337-f19d7cfbcce8', 'concept'::public.curated_course_node_type, 'Recording discoveries in an actor''s notebook', null, 2),
  ('aa7f34da-e1cb-44ad-83ef-73b5540a697a', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'a5534290-763e-4993-86db-27dee47a0369', 'subtopic'::public.curated_course_node_type, 'Coaching and Revision', 'Students learn to use notes without losing ownership of choices.', 2),
  ('e99b578a-ab59-47b9-84ae-e7910b8a247e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'aa7f34da-e1cb-44ad-83ef-73b5540a697a', 'concept'::public.curated_course_node_type, 'Receiving instructor and peer feedback', null, 0),
  ('9970bd9c-1053-441b-a094-a68643d4b8a5', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'aa7f34da-e1cb-44ad-83ef-73b5540a697a', 'concept'::public.curated_course_node_type, 'Translating notes into playable adjustments', null, 1),
  ('a325003b-deb4-445f-8a37-83120ce50f73', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'aa7f34da-e1cb-44ad-83ef-73b5540a697a', 'concept'::public.curated_course_node_type, 'Avoiding fixed line readings and premature polish', null, 2),
  ('3cb5968a-fb14-40d2-8f1b-0e6c5d439d90', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Character Work and Transformation', 'Character work asks students to build truthful behavior from circumstances, body, voice, imagination, and relationship. The emphasis is transformation with respect, not stereotype.', 8),
  ('85c5acf0-4d85-43db-9007-db557dd6b504', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '3cb5968a-fb14-40d2-8f1b-0e6c5d439d90', 'subtopic'::public.curated_course_node_type, 'Character Given Circumstances', 'Students synthesize background facts into behavior rather than biography for its own sake.', 0),
  ('fc3e653f-ae65-4a48-bb0c-ce4c314f225f', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '85c5acf0-4d85-43db-9007-db557dd6b504', 'concept'::public.curated_course_node_type, 'History, need, relationships, social world, and secrets', null, 0),
  ('e12bdfd0-2103-4c65-b55e-916012ce7672', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '85c5acf0-4d85-43db-9007-db557dd6b504', 'concept'::public.curated_course_node_type, 'What the character knows versus what the actor knows', null, 1),
  ('81ecf116-f162-4870-9567-b9e9dc9dec40', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '85c5acf0-4d85-43db-9007-db557dd6b504', 'concept'::public.curated_course_node_type, 'Character research connected to playable action', null, 2),
  ('16e65b5c-387c-4180-b34f-2adec7064bda', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '3cb5968a-fb14-40d2-8f1b-0e6c5d439d90', 'subtopic'::public.curated_course_node_type, 'Physical and Vocal Choices', 'Actors explore how character lives in rhythm, posture, speech, and movement.', 1),
  ('9c60074a-7edf-4b8a-bee5-b99fcd3e22a8', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '16e65b5c-387c-4180-b34f-2adec7064bda', 'concept'::public.curated_course_node_type, 'Center, tempo, weight, gesture, and habitual action', null, 0),
  ('88be37c3-b6ad-418c-9a5c-069a37d48dd9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '16e65b5c-387c-4180-b34f-2adec7064bda', 'concept'::public.curated_course_node_type, 'Voice placement, pace, diction, and energy', null, 1),
  ('9131689f-0bee-4ee2-8565-6a5e400e6bbc', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '16e65b5c-387c-4180-b34f-2adec7064bda', 'concept'::public.curated_course_node_type, 'Consistency without mechanical repetition', null, 2),
  ('7084326d-f16e-4afc-be51-7fefcd22ffdc', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '3cb5968a-fb14-40d2-8f1b-0e6c5d439d90', 'subtopic'::public.curated_course_node_type, 'Ethics of Representation', 'The unit builds responsibility around identity, culture, trauma, disability, class, and accent.', 2),
  ('fc2c723b-7a2b-4de4-b979-8856ebab88e9', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7084326d-f16e-4afc-be51-7fefcd22ffdc', 'concept'::public.curated_course_node_type, 'Research beyond stereotype', null, 0),
  ('3c44f798-a7b8-4a0f-af10-e765a597adb7', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7084326d-f16e-4afc-be51-7fefcd22ffdc', 'concept'::public.curated_course_node_type, 'Consent and care when working with vulnerable material', null, 1),
  ('44c5f167-78ac-4b13-ba1d-ec12a272aa81', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7084326d-f16e-4afc-be51-7fefcd22ffdc', 'concept'::public.curated_course_node_type, 'Respectful boundaries around accent, body, and lived experience', null, 2),
  ('9cab4b79-5771-41e7-9975-6ef39a01e7ed', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Ensemble Practice and Collaboration', 'Acting is never purely solo. Students learn ensemble awareness, shared rhythm, trust, and accountability as artistic skills that shape both process and performance.', 9),
  ('190543c6-95ec-43de-af3d-6d450e519a06', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9cab4b79-5771-41e7-9975-6ef39a01e7ed', 'subtopic'::public.curated_course_node_type, 'Group Awareness', 'Students train attention across the whole room, not only their own part.', 0),
  ('651db367-06e7-41ce-b0f8-ab5c6758b4c8', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '190543c6-95ec-43de-af3d-6d450e519a06', 'concept'::public.curated_course_node_type, 'Peripheral awareness, shared tempo, group focus, and cueing', null, 0);
