  ('8d7cfd18-ef36-4cb0-81fd-a86f2ca54b42', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '294f4df3-0f5d-485a-aecb-f6b5d71aedc3', 'concept'::public.curated_course_node_type, 'Repair after miscommunication', null, 2),
  ('7fba1909-5582-4ca0-98ef-afd90f2c8c53', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9cab4b79-5771-41e7-9975-6ef39a01e7ed', 'subtopic'::public.curated_course_node_type, 'Peer Feedback', 'Students practice critique that is specific, kind, useful, and craft-based.', 2),
  ('e8817a9d-f11a-4ba6-9d8a-320a7962ec4e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7fba1909-5582-4ca0-98ef-afd90f2c8c53', 'concept'::public.curated_course_node_type, 'Observation before evaluation', null, 0),
  ('832932e3-6078-41a9-a74f-2016bbc7c8ba', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7fba1909-5582-4ca0-98ef-afd90f2c8c53', 'concept'::public.curated_course_node_type, 'Feedback on actions, clarity, stakes, and listening', null, 1),
  ('95b8363d-4ac5-47de-8a31-d421a5539e43', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '7fba1909-5582-4ca0-98ef-afd90f2c8c53', 'concept'::public.curated_course_node_type, 'Separating taste from evidence', null, 2),
  ('40ca209f-e520-4010-9c1b-a375f62b26b5', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', null, 'topic'::public.curated_course_node_type, 'Rehearsal Process and Professional Practice', 'A strong Acting I course should teach craft and conduct together. Students build habits that prepare them for productions, auditions, crews, and future studio sequences.', 10),
  ('ba7e46b1-56a1-447a-a915-fe3d7a991188', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '40ca209f-e520-4010-9c1b-a375f62b26b5', 'subtopic'::public.curated_course_node_type, 'Rehearsal Discipline', 'Students learn that preparation is an ethical obligation to collaborators.', 0),
  ('a947505f-7467-4362-bd59-cc067f2e17ca', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'ba7e46b1-56a1-447a-a915-fe3d7a991188', 'concept'::public.curated_course_node_type, 'Punctuality, memorization, script care, and rehearsal clothes', null, 0),
  ('d8175d54-c3b4-4bc0-b7e9-4cec1a810db0', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'ba7e46b1-56a1-447a-a915-fe3d7a991188', 'concept'::public.curated_course_node_type, 'Notes etiquette and communication norms', null, 1),
  ('dab6bf92-f353-4c79-8a5e-522859c93213', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'ba7e46b1-56a1-447a-a915-fe3d7a991188', 'concept'::public.curated_course_node_type, 'Tracking blocking, props, cuts, and changes', null, 2),
  ('462f23b4-39ac-4782-a664-ac58edd25d9f', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '40ca209f-e520-4010-9c1b-a375f62b26b5', 'subtopic'::public.curated_course_node_type, 'Audition and Monologue Foundations', 'The course introduces audition readiness without turning Acting I into an audition class.', 1),
  ('d9e8bb5b-4a8a-4000-b088-b08e9cc12a09', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '462f23b4-39ac-4782-a664-ac58edd25d9f', 'concept'::public.curated_course_node_type, 'Choosing age-appropriate material', null, 0),
  ('eadb8cf7-cbbf-4c19-885d-4b0c787b127c', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '462f23b4-39ac-4782-a664-ac58edd25d9f', 'concept'::public.curated_course_node_type, 'Slate, entrance, focus, and reset', null, 1),
