  ('79fe3ebd-20ff-47c7-8e29-ebfbe0d78a2a', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b8e389ce-ade1-4961-a3b7-c7aa027d01b7', 'concept'::public.curated_course_node_type, 'Director, stage manager, designer, dramaturg, and crew roles', null, 0),
  ('42ec0478-7e9b-4412-8779-9bbd9d8c560b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b8e389ce-ade1-4961-a3b7-c7aa027d01b7', 'concept'::public.curated_course_node_type, 'Rehearsal room, tech, dress rehearsal, and performance etiquette', null, 1),
  ('643aa7e0-82a0-46aa-bb10-dbb769c69f7b', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b8e389ce-ade1-4961-a3b7-c7aa027d01b7', 'concept'::public.curated_course_node_type, 'Safety, access, and workplace expectations', null, 2),
