  ('a7fddd47-eca1-4dbe-8cc6-5d91f6dd6091', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b3e8eb86-178c-444d-b0e1-ccb5929a3570', 'concept'::public.curated_course_node_type, 'Memorized scene with rehearsed blocking', null, 0),
  ('eb034376-c6d8-4ef8-87a4-52d2ccbf53f4', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b3e8eb86-178c-444d-b0e1-ccb5929a3570', 'concept'::public.curated_course_node_type, 'Specific given circumstances and playable actions', null, 1),
  ('b38d457b-3010-4418-a45f-528b6ec66aeb', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'b3e8eb86-178c-444d-b0e1-ccb5929a3570', 'concept'::public.curated_course_node_type, 'Recovery, presence, and responsiveness under audience attention', null, 2),
  ('9f403817-6678-4e68-9295-3fcbe6780a20', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'de32f029-737a-4ea2-8698-cb6bc530fdb5', 'subtopic'::public.curated_course_node_type, 'Performance Response', 'Students learn to discuss acting choices using evidence rather than vague praise or preference.', 1),
  ('e39df48b-bf0f-4ba4-92e6-17f7c62b8e18', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9f403817-6678-4e68-9295-3fcbe6780a20', 'concept'::public.curated_course_node_type, 'What changed in performance', null, 0),
