  ('de4e0332-140d-4c0b-a4c4-2570be1b83a1', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '9f403817-6678-4e68-9295-3fcbe6780a20', 'concept'::public.curated_course_node_type, 'Craft-based self-assessment and peer response', null, 2),
  ('2208cb48-6a96-441e-87d9-68dbb03f697e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', 'de32f029-737a-4ea2-8698-cb6bc530fdb5', 'subtopic'::public.curated_course_node_type, 'Actor''s Development Plan', 'The course ends by turning feedback into a practical training plan.', 2),
  ('771c37f7-3f87-4916-866d-81c62be3091e', 'e1f2a3b4-5c6d-4e21-8a01-1b2c3d4e5f21', '2208cb48-6a96-441e-87d9-68dbb03f697e', 'concept'::public.curated_course_node_type, 'Strengths, growth edges, and next studio goals', null, 0),
